use crate::{ConfigError, ConfigErrorKind, merge::DefaultMerge, source::Source};
use figment::Figment;
use serde::{Serialize, de::DeserializeOwned};
use std::{
    any::{Any, TypeId},
    path::Path,
    sync::Arc,
};

pub type ValidationError = Box<dyn std::error::Error + Send + Sync>;

/// A registered configuration section, implemented by `#[derive(Config)]`.
///
/// Use this bound in helpers that call [`crate::LoadedConfig::get`]. Nested
/// `ConfigValue` types are accessed through their owning section instead.
/// Implementations are generated by the derive macro, not written manually.
///
/// ```
/// use ah_config::{ConfigError, ConfigSection, LoadedConfig};
/// use std::sync::Arc;
///
/// fn read<T: ConfigSection>(config: &LoadedConfig) -> Result<Arc<T>, ConfigError> {
///     config.get::<T>()
/// }
/// ```
#[diagnostic::on_unimplemented(
    message = "`{Self}` is not a configuration section; derive ah_config::Config and access ConfigValue through its owning section"
)]
pub trait ConfigSection: Send + Sync + 'static {
    /// The complete TOML section path, including all declared parents.
    const KEY: &'static str;
}

/// Read-only metadata for a linked section, without evaluating its configuration.
#[derive(Debug)]
pub struct SectionInfo {
    key: &'static str,
    type_name: &'static str,
    spaces: &'static [&'static str],
}

impl SectionInfo {
    /// The complete TOML path, including all declared parents.
    pub fn key(&self) -> &'static str {
        self.key
    }

    /// The fully qualified Rust type name, intended for diagnostics.
    pub fn type_name(&self) -> &'static str {
        self.type_name
    }

    /// The declared space memberships; parent memberships are not inherited.
    pub fn spaces(&self) -> &'static [&'static str] {
        self.spaces
    }
}

/// Field ownership metadata used by the derive macro's parent checks.
pub trait SectionFields {
    const FIELDS: &'static [&'static str];
}

/// Implemented only for named struct sections without `deny_unknown_fields`.
#[diagnostic::on_unimplemented(
    message = "`{Self}` must be a Config named struct without deny_unknown_fields to allow external child sections"
)]
pub trait ExtensibleSection: ConfigSection + SectionFields {}

/// Construct a child's full key and reject ownership of an existing parent field.
pub const fn child_key<P: ExtensibleSection, const N: usize>(key: &str) -> [u8; N] {
    let mut index = 0;
    while index < P::FIELDS.len() {
        assert!(
            !same_bytes(P::FIELDS[index].as_bytes(), key.as_bytes()),
            "child section key is already owned by a parent field"
        );
        index += 1;
    }
    let parent = P::KEY.as_bytes();
    let child = key.as_bytes();
    let mut bytes = [0; N];
    index = 0;
    while index < parent.len() {
        bytes[index] = parent[index];
        index += 1;
    }
    bytes[index] = b'.';
    index += 1;
    let mut offset = 0;
    while offset < child.len() {
        bytes[index + offset] = child[offset];
        offset += 1;
    }
    bytes
}

const fn same_bytes(left: &[u8], right: &[u8]) -> bool {
    if left.len() != right.len() {
        return false;
    }
    let mut index = 0;
    while index < left.len() {
        if left[index] != right[index] {
            return false;
        }
        index += 1;
    }
    true
}

pub(crate) type SharedValue = Arc<dyn Any + Send + Sync>;
type Validator<T> = fn(&T) -> Result<(), ValidationError>;
type Loader = Box<dyn Fn(&Figment, &Path, bool) -> Result<SharedValue, ConfigError> + Send + Sync>;

pub struct Declaration {
    pub(crate) key: &'static str,
    pub(crate) spaces: &'static [&'static str],
    pub(crate) type_id: fn() -> TypeId,
    type_name: fn() -> &'static str,
    pub(crate) prepare: fn() -> Result<Prepared, ConfigError>,
}

impl Declaration {
    pub const fn new<T: 'static>(
        key: &'static str,
        spaces: &'static [&'static str],
        prepare: fn() -> Result<Prepared, ConfigError>,
    ) -> Self {
        Self {
            key,
            spaces,
            type_id: TypeId::of::<T>,
            type_name: std::any::type_name::<T>,
            prepare,
        }
    }

    pub(crate) fn info(&self) -> SectionInfo {
        SectionInfo {
            key: self.key,
            type_name: (self.type_name)(),
            spaces: self.spaces,
        }
    }
}

#[linkme::distributed_slice]
pub static DECLARATIONS: [Declaration];

pub struct Prepared {
    pub(crate) key: &'static str,
    pub(crate) type_id: TypeId,
    pub(crate) defaults: Option<Source>,
    pub(crate) replace: bool,
    pub(crate) empty: Source,
    pub(crate) prepare_defaults: fn(&mut Source, &Source, &str),
    pub(crate) load: Loader,
}

pub fn prepare<T>(
    key: &'static str,
    defaults: Option<T>,
    validate: Option<Validator<T>>,
    replace: bool,
) -> Result<Prepared, ConfigError>
where
    T: Serialize + DeserializeOwned + DefaultMerge + Send + Sync + 'static,
{
    let defaults = defaults
        .map(|value| Source::defaults(key, value))
        .transpose()?;
    let has_defaults = defaults.is_some();
    let empty = Source::defaults(key, std::collections::BTreeMap::<String, ()>::new())?;
    let load = Box::new(move |figment: &Figment, path: &Path, from_file: bool| {
        let value: T = figment.extract_inner(key).map_err(|error| {
            let kind = if from_file {
                ConfigErrorKind::Deserialize
            } else if !has_defaults && matches!(error.kind, figment::error::Kind::MissingField(_)) {
                ConfigErrorKind::MissingSection
            } else {
                ConfigErrorKind::Defaults
            };
            ConfigError::decode(kind, path, key, error)
        })?;
        if let Some(validate) = validate {
            validate(&value).map_err(|error| {
                ConfigError::for_section(ConfigErrorKind::Validation, path, key, error)
            })?;
        }
        Ok(Arc::new(value) as SharedValue)
    });
    Ok(Prepared {
        key,
        type_id: TypeId::of::<T>(),
        defaults,
        replace,
        empty,
        prepare_defaults: Source::prepare_defaults::<T>,
        load,
    })
}
